         outer_inner_idx += gridDim.x * elements_per_block) {

        // Calculate the outer and inner indices for this block
        int64_t outer_idx = outer_inner_idx / inner_size;
        int64_t inner_idx = outer_inner_idx % inner_size;

        // Initialize sum for this element
        float sum_val = 0.0f;

        // Each thread processes multiple elements if necessary
        for (int64_t offset = 0; offset < reduce_dim_size; offset += blockDim.x) {
            int64_t input_idx = outer_idx * reduce_dim_size * inner_size + offset * inner_size + inner_idx;

            // Load and accumulate
            if (offset + tid < reduce_dim_size) {
                sum_val += __half2float(input[input_idx]);
