        // Reduction in shared memory
        sdata[tid] = sum_val;
        __syncthreads();

        // Perform reduction in shared memory
        for (int64_t s = blockDim.x / 2; s > 0; s >>= 1) {
            if (tid < s) {
                sdata[tid] += sdata[tid + s];
            }
            __syncthreads();
        }

        // Write result for this thread to global memory
        if (tid == 0) {
            int64_t output_idx = outer_idx * inner_size + inner_idx;
            output[output_idx] = __float2half(sdata[0]);
        }
    }
